//! Closed JC097. Project ruling: freeze derived raid X at the reveal event.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="JC097";
pub(crate) const KEY:&str="raid-jc097";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Observation{pub event_id:String,pub turn:u32,pub corpses:Vec<Card>}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn owns(o:&Op)->bool{match o{Op::JC097Raid{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key==KEY||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key==KEY||f.steps.iter().any(|s|owns(&s.op))}
pub(crate) fn definition()->Definition{let mut d=with_abilities(vec![ability(KEY,"袭击X：现身时本人墓地角色数量",Timing::Fast,vec![],vec![target(Zone::Board,EntityKind::Character,Relation::Any,Range::SourceRegion)],vec![Op::JC097Raid{observation:None}],Some(Event::Reveal))]);d.traits.stealth=true;d}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.remove(0);if let [Op::JC097Raid{observation}]=a.ops.as_slice(){expected.ops=vec![Op::JC097Raid{observation:observation.clone()}];}if id!=ID||!same(a,&expected){return Err("阿斯旺必须保留完整原定义".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("阿斯旺规则不可移植或增删".into());}Ok(())}
impl Game{
 pub(crate) fn jc097_reveal_ability(&mut self,source:&Card)->AbilitySpec{let corpses=self.bq095_reference_cards(source).iter().filter(|c|catalog::card(&c.definition).kind=="character").cloned().collect();let observation=Observation{event_id:self.id(),turn:self.turn,corpses};let mut a=definition().abilities.remove(0);a.ops=vec![Op::JC097Raid{observation:Some(observation)}];a}
 fn jc097_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=actor||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("阿斯旺原现身来源损坏".into());}self.mobility_immutable_identity(c)}
 fn jc097_observation(&self,actor:usize,s:&SourceSnapshot,ops:&[Op])->RuleResult<()>{let [Op::JC097Raid{observation:Some(o)}]=ops else{return Err("阿斯旺缺少实际现身观察".into());};let mut seen=BTreeSet::new();if o.turn!=self.turn||!self.mystic_instance_number(&o.event_id).zip(self.mystic_instance_number(&s.card.id)).is_some_and(|(e,c)|e>c){return Err("阿斯旺事件身份损坏".into());}for c in &o.corpses{if c.owner!=self.bq095_frozen_reference_seat(&s.card,&o.event_id)||c.controller!=c.owner||c.face_down||c.generated.is_some()||catalog::card(&c.definition).kind!="character"||!seen.insert(&c.id)||!self.mystic_instance_number(&o.event_id).zip(self.mystic_instance_number(&c.id)).is_some_and(|(e,c)|e>c){return Err("阿斯旺原墓地角色观察损坏".into());}self.mobility_immutable_identity(c)?;}Ok(())}
 pub(crate) fn validate_jc097_declaration(&self,d:&Declaration)->RuleResult<()>{if !related(&d.ability){if d.source.card.definition==ID&&!self.validated_cross_card_declaration(d)?{return Err("阿斯旺不能携带外来声明".into());}return Ok(());}self.jc097_source(d.actor,&d.source)?;validate_ability(ID,&d.ability)?;self.jc097_observation(d.actor,&d.source,&d.ability.ops)}
 pub(crate) fn validate_jc097_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){if f.source.card.definition==ID&&!matches!(f.ability_key.as_str(),"deploy"|"reveal")&&!self.validated_cross_card_frame(f)?{return Err("阿斯旺不能携带外来帧".into());}return Ok(());}self.jc097_source(f.actor,&f.source)?;let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();self.jc097_observation(f.actor,&f.source,&ops)?;if f.ability_key!=KEY||!self.mystic_instance_valid(&f.frame_id)||f.frame_id==f.source.card.id||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.already_paid.is_empty()||!f.resource_payments.is_empty()||f.chosen_region.is_some()||f.steps.iter().any(|s|s.context!=f.actor)||f.targets.len()!=1{return Err("阿斯旺程序或响应阶段损坏".into());}let t=&f.targets[0];if !same(&t.spec,&definition().abilities[0].targets[0])||!self.mystic_instance_valid(&t.id)||t.region_instance.is_some()||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some()||t.public.kind!="character"||t.public.region!=f.source.region{return Err("阿斯旺原本地区角色目标损坏".into());}Ok(())}
 pub(crate) fn jc097_raid(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_jc097_frame(f)?;if f.cursor!=1{return Err("阿斯旺袭击须经原目标守卫".into());}let Op::JC097Raid{observation:Some(o)}=&f.steps[0].op else{unreachable!()};if !self.players[f.actor].eliminated&&self.valid_bound_target(f.actor,&f.source,&f.targets[0]){self.damage([(f.targets[0].id.clone(),o.corpses.len()as u32)].into_iter().collect())?;}Ok(())}
 pub(crate) fn validate_jc097_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut remember=|s:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{if let [Op::JC097Raid{observation:Some(d)}]=ops{if !seen.insert((s.card.id.clone(),d.event_id.clone())){return Err("阿斯旺同一墓地事件重复载体".into());}}Ok(())};for i in &self.stack{self.validate_jc097_play(i)?;if let Some(f)=&i.frame{self.validate_jc097_frame(f)?;if frame_related(f){self.validate_jc097_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;if i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.reveal||i.deploy_region.is_some()||i.target!=f.targets.first().map(|t|t.id.clone())||f.cursor!=0{return Err("阿斯旺响应外壳损坏".into());}}}}for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)||d.source.card.definition==ID=>{self.validate_jc097_declaration(d)?;remember(&d.source,&d.ability.ops)?;},Effect::Frame{frame:f}if frame_related(f)=>return Err("阿斯旺单步没有游离续体".into()),_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}if related(&d.ability)||d.source.card.definition==ID=>{self.validate_jc097_declaration(d)?;if !related(&d.ability){return Ok(());}remember(&d.source,&d.ability.ops)?;let options=self.binding_options(d.actor,&d.source,&d.ability.targets[0]);let expected=Choice{id:p.choice.id.clone(),kind:"trigger".into(),title:format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options,preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if !matches!(stage,DeclareChoice::Target)||!self.mystic_instance_valid(&p.choice.id)||p.seat!=d.actor||expected.options.is_empty()||!same(&p.choice,&expected){return Err("阿斯旺触发选择损坏".into());}},ChoiceResolution::Frame{frame:f,..}if frame_related(f)=>return Err("阿斯旺没有执行中待选".into()),_=>()}}Ok(())}
}
impl Game{
 pub(crate) fn validate_jc097_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|c.definition==ID)&&!item.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("JC097角色事务缺少原帧")?;let c=&f.source.card;
  if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||f.ability_key!="reveal"||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=3&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("JC097角色事务、原帧或实际牌面不符".into());}self.mobility_immutable_identity(c)
 }

}

pub(crate) fn validate_choice(p:&Pending,a:&Action)->RuleResult<()>{let ours=match &p.resolution{ChoiceResolution::Declare{declaration:d,..}=>related(&d.ability),ChoiceResolution::Frame{frame:f,..}=>frame_related(f),_=>false};if ours&&*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("阿斯旺选择不能夹带额外载荷".into());}Ok(())}
